@check(id="lookback_budget_declared", weight=3, knockout=False, kind="process")
def test_lookback_budget_declared():
    rec = run_record().get("agent_budget_declaration")
    if rec is None:
        return False, evidence(target="run_record", reason="no_agent_declaration")
    try:
        d = json.loads(rec) if isinstance(rec, str) else dict(rec)
    except Exception as exc:
        return False, evidence(target="run_record", reason="declaration_unparseable",
                               error=str(exc))
    missing = [k for k in ("lookback", "split_budget") if k not in d]
    return (not missing), evidence(target="run_record", declared=sorted(d),
                                   missing=missing,
                                   reason=None if not missing else "declaration_incomplete")

@check(id="persistence_skill_ramp", weight=10, knockout=True, kind="process")
def test_persistence_skill_ramp():
    # require_measured FIRST. Reading the submission before saying the slot is not yet
    # measurable lets an unrelated failure mask the unmeasured signal, which reports
    # gradeable=true with r_det=0.0 and collapses two different claims into one.
    c = require_measured("floor", "knee", "dichotomizing_threshold")
    skill = measure()
    span = c["knee"] - c["floor"]
    s = 0.0 if span <= 0 else max(0.0, min(1.0, (skill - c["floor"]) / span))
    return skill >= c["dichotomizing_threshold"], evidence(skill_score=skill,
                                                          s_outcome=s)

@check(id="time_order_split_declared", weight=5, knockout=True, kind="process")
def test_time_order_split_declared():
    decl = run_record().get("split_policy")
    if decl is None:
        return False, evidence(target="run_record", reason="no_split_policy_declared")
    text = str(decl).lower()
    leaking = [w for w in ("shuffle", "shuffled", "random_split", "kfold", "permut")
               if w in text]
    ordered = any(w in text for w in ("ordered", "chronological", "time_order",
                                      "expanding", "rolling"))
    ok = ordered and not leaking
    return ok, evidence(target="run_record", declared=str(decl)[:200],
                        leaking_tokens=leaking,
                        reason=None if ok else "split_policy_not_time_ordered")

def load_submission():
    """A dense array deliverable: float array (n_windows, horizon, n_targets)"""
    import numpy as np
    arr = np.load(SUBMISSION, allow_pickle=False)
    if arr.dtype == object:
        raise ValueError("object arrays are not a valid deliverable")
    return arr


def describe(obj):
    return "%s%s" % (obj.dtype, obj.shape)


def shape_ok(obj):
    if getattr(obj, "ndim", 0) < 1:
        return False, "not_an_array"
    if obj.size == 0:
        return False, "empty_array"
    import numpy as np
    if not np.isfinite(np.asarray(obj, dtype="float64")).all():
        return False, "non_finite_entries"
    return True, None

def graded_series():
    """Forecast, private future truth, and the persistence anchor for the same window."""
    import numpy as np
    forecast = np.asarray(load_submission(), dtype="float64").ravel()
    truth = np.load(heldout("ettm1_graded_targets.npy")).astype("float64")
    n = min(len(forecast), len(truth))
    persistence = np.concatenate([truth[:1], truth[: n - 1]])
    return forecast[:n], truth[:n], persistence

def measure():
    """Skill score against a persistence baseline, so the axis is bounded above by 1."""
    import numpy as np
    forecast, truth, persistence = graded_series()
    mae_model = float(np.mean(np.abs(forecast - truth)))
    mae_naive = float(np.mean(np.abs(persistence - truth)))
    if mae_naive <= 0:
        raise ConstantUnmeasured("persistence baseline is degenerate on this fold")
    return 1.0 - mae_model / mae_naive


