def constants_json():
    with open(os.path.join(HERE, "constants.json")) as handle:
        return json.load(handle)


def heldout(name):
    return os.path.join(HERE, "heldout", name)


def run_record():
    path = os.path.join(HERE, "..", "run_record.json")
    if not os.path.exists(path):
        return {}
    with open(path) as handle:
        return json.load(handle)


def guarded_paths_touched():
    """Paths under the checker tree or graded fold modified during the graded run.

    Read from the harness record the run itself produced, never from a scan performed after the
    fact: a post-hoc scan cannot separate a write made during the graded run from one made before.
    """
    return run_record().get("guarded_paths_touched", [])


def artifact_digest():
    import hashlib
    if not os.path.exists(SUBMISSION):
        return None
    return hashlib.sha256(open(SUBMISSION, "rb").read()).hexdigest()


def replay_digest():
    return run_record().get("replay_artifact_sha256")
